#[test]
fn multiple_component_and_lane_index_repair_matches_node() {
    let helper = Helper::new();
    helper.re_init_workspace();
    helper.populate_components(2, true, "");
    helper.tag_without_build("", "--message fixture");
    helper.run("lane create fixture");
    helper.append_file("comp1/index.js", "\n// lane");
    helper.run("snap --message lane");
    parity_options(&helper, "init --reset", true, true);
    if cfg!(windows) {
        assert!(!helper.scopes.local_path.join(".bit/index.json").exists());
        return;
    }
    let index: serde_json::Value = serde_json::from_slice(
        &fs::read(helper.scopes.local_path.join(".bit/index.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(
        index["components"]
            .as_array()
            .unwrap()
            .len(),
        2,
    );
    assert_eq!(index["lanes"].as_array().unwrap().len(), 1);
}
